@theme inline {
  --font-sans: /* 'MyriadPro',  */'Open Sans', sans-serif;
  --font-serif: 'EB Garamond', 'Times New Roman', Times, serif;

  --radius-xs: 0.25rem;
  --radius-sm: 0.25rem;
  --radius-md: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-xl: 0.5rem;
  --radius-2xl: 1rem;
  --radius-full: calc(infinity * 1px);

  --color-uib-red-050: oklch(0.9838 0.0118 79.79);
  --color-uib-red-100: oklch(0.9157 0.0456 41.83);
  --color-uib-red-200: oklch(0.8312 0.0942 30.47);
  --color-uib-red-300: oklch(0.7611 0.143 30.54);
  --color-uib-red-400: oklch(0.7164 0.1774 28.33);
  --color-uib-red-500: oklch(0.6245 0.2117 26.09);
  --color-uib-red-600: oklch(0.4714 0.1821 27.16);
  --color-uib-red-700: oklch(0.3751 0.1266 26.27);
  --color-uib-red-800: oklch(0.2127 0.0622 25.49);
  --color-uib-red-900: oklch(0.1643 0.0417 22.81);
  --color-uib-red-950: oklch(0.1192 0.0241 21.34);
  --color-uib-green-050: oklch(0.984 0.015 158.259);
  --color-uib-green-100: oklch(0.957 0.051 160.06);
  --color-uib-green-200: oklch(0.914 0.088 157.653);
  --color-uib-green-300: oklch(0.879 0.125 156.483);
  --color-uib-green-400: oklch(0.755 0.156 160.687);
  --color-uib-green-500: oklch(0.637 0.142 155.67);
  --color-uib-green-600: oklch(0.539 0.12 160.348);
  --color-uib-green-700: oklch(0.452 0.096 163.969);
  --color-uib-green-800: oklch(0.276 0.057 156.656);
  --color-uib-green-900: oklch(0.2 0.038 157.374);
  --color-uib-green-950: oklch(0.133 0.019 172.387);
  --color-uib-blue-050: oklch(0.982 0.01 212.522);
  --color-uib-blue-100: oklch(0.927 0.039 241.042);
  --color-uib-blue-200: oklch(0.882 0.06 246.199);
  --color-uib-blue-300: oklch(0.83 0.086 247.374);
  --color-uib-blue-400: oklch(0.751 0.134 248.907);
  --color-uib-blue-500: oklch(0.673 0.159 241.744);
  --color-uib-blue-600: oklch(0.547 0.144 247.071);
  --color-uib-blue-700: oklch(0.376 0.117 253.288);
  --color-uib-blue-800: oklch(0.257 0.096 258.769);
  --color-uib-blue-900: oklch(0.177 0.059 255.586);
  --color-uib-blue-950: oklch(0.119 0.042 256.948);
  --color-uib-neutral-050: oklch(0.982 0 0);
  --color-uib-neutral-100: oklch(0.927 0 0);
  --color-uib-neutral-200: oklch(0.882 0 0);
  --color-uib-neutral-300: oklch(0.83 0 0);
  --color-uib-neutral-400: oklch(0.751 0 0);
  --color-uib-neutral-500: oklch(0.673 0 0);
  --color-uib-neutral-600: oklch(0.547 0 0);
  --color-uib-neutral-700: oklch(0.376 0 0);
  --color-uib-neutral-800: oklch(0.257 0 0);
  --color-uib-neutral-900: oklch(0.177 0 0);
  --color-uib-neutral-950: oklch(0.119 0 0);
  --color-uib-beige: oklch(0.916 0.019 80.115);

  /* UiB typography tokens */
  --font-size-body-small-on-mobile: 0.875rem;
  --font-size-body-small-on-desktop: 1rem;
  --font-size-body-on-mobile: 1rem;
  --font-size-body-on-desktop: 1.25rem;
  --font-size-action-on-mobile: 1.125rem;
  --font-size-action-on-desktop: 1.25rem;
  --font-size-lead-on-mobile: 1.25rem;
  --font-size-lead-on-desktop: 1.5rem;
  --font-size-h6-on-mobile: 1rem;
  --font-size-h6-on-desktop: 1.25rem;
  --font-size-h5-on-mobile: 1.125rem;
  --font-size-h5-on-desktop: 1.375rem;
  --font-size-h4-on-mobile: 1.25rem;
  --font-size-h4-on-desktop: 1.5rem;
  --font-size-h3-on-mobile: 1.5rem;
  --font-size-h3-on-desktop: 2rem;
  --font-size-h2-on-mobile: 2rem;
  --font-size-h2-on-desktop: 2.5rem;
  --font-size-h1-on-mobile: 2.25rem;
  --font-size-h1-on-desktop: 3rem;
  --font-size-hero-on-mobile: 2.75rem;
  --font-size-hero-on-desktop: 3.75rem;
  --font-size-blockquote-on-mobile: 1.5rem;
  --font-size-blockquote-on-desktop: 2rem;

  /* UiB space tokens */
  --space-0-on-mobile: 0;
  --space-0-on-desktop: 0;
  --space-1-on-mobile: 0.25rem;
  --space-1-on-desktop: 0.25rem;
  --space-2-on-mobile: 0.25rem;
  --space-2-on-desktop: 0.5rem;
  --space-3-on-mobile: 0.5rem;
  --space-3-on-desktop: 0.75rem;
  --space-4-on-mobile: 0.75rem;
  --space-4-on-desktop: 1rem;
  --space-5-on-mobile: 1rem;
  --space-5-on-desktop: 1.25rem;
  --space-6-on-mobile: 1.25rem;
  --space-6-on-desktop: 1.5rem;
  --space-8-on-mobile: 1.5rem;
  --space-8-on-desktop: 2rem;
  --space-10-on-mobile: 2rem;
  --space-10-on-desktop: 2.5rem;
  --space-12-on-mobile: 2.5rem;
  --space-12-on-desktop: 3rem;
  --space-14-on-mobile: 3rem;
  --space-14-on-desktop: 3.5rem;
  --space-16-on-mobile: 3rem;
  --space-16-on-desktop: 4rem;
  --space-24-on-mobile: 4rem;
  --space-24-on-desktop: 6rem;
  --space-32-on-mobile: 6rem;
  --space-32-on-desktop: 8rem;
  --clamp-1: 0.333vw;
  --clamp-2: 0.667vw;
  --clamp-3: 1vw;
  --clamp-4: 1.333vw;
  --clamp-5: 1.667vw;
  --clamp-6: 2vw;
  --clamp-8: 2.667vw;
  --clamp-10: 3.333vw;
  --clamp-12: 4vw;
  --clamp-14: 4.667vw;
  --clamp-16: 5.417vw;
  --clamp-24: 8vw;
  --clamp-32: 10.667vw;
  /* Fluid spacing aliases for functional utilities (fl-*) */
  --fl-space-0: clamp(var(--space-0-on-mobile), var(--clamp-1), var(--space-0-on-desktop));
  --fl-space-1: clamp(var(--space-1-on-mobile), var(--clamp-1), var(--space-1-on-desktop));
  --fl-space-2: clamp(var(--space-2-on-mobile), var(--clamp-2), var(--space-2-on-desktop));
  --fl-space-3: clamp(var(--space-3-on-mobile), var(--clamp-3), var(--space-3-on-desktop));
  --fl-space-4: clamp(var(--space-4-on-mobile), var(--clamp-4), var(--space-4-on-desktop));
  --fl-space-5: clamp(var(--space-5-on-mobile), var(--clamp-5), var(--space-5-on-desktop));
  --fl-space-6: clamp(var(--space-6-on-mobile), var(--clamp-6), var(--space-6-on-desktop));
  --fl-space-8: clamp(var(--space-8-on-mobile), var(--clamp-8), var(--space-8-on-desktop));
  --fl-space-10: clamp(var(--space-10-on-mobile), var(--clamp-10), var(--space-10-on-desktop));
  --fl-space-12: clamp(var(--space-12-on-mobile), var(--clamp-12), var(--space-12-on-desktop));
  --fl-space-14: clamp(var(--space-14-on-mobile), var(--clamp-14), var(--space-14-on-desktop));
  --fl-space-16: clamp(var(--space-16-on-mobile), var(--clamp-16), var(--space-16-on-desktop));
  --fl-space-24: clamp(var(--space-24-on-mobile), var(--clamp-24), var(--space-24-on-desktop));
  --fl-space-32: clamp(var(--space-32-on-mobile), var(--clamp-32), var(--space-32-on-desktop));

  /* UiB button tokens */
  --color-button-primary-foreground: var(--button-color-fg-primary);
  --color-button-secondary-foreground: var(--button-color-fg-secondary-idle);
  --color-button-secondary-foreground-active: var(--button-color-fg-secondary-active);
  --color-button-secondary-foreground-active-on-beige: var(--button-color-fg-secondary-active-on-beige);
  --color-button-tertiary-foreground: var(--button-color-fg-tertiary-idle);
  --color-button-primary: var(--button-color-bg-primary-idle);
  --color-button-primary-active: var(--button-color-bg-primary-active);
  --color-button-secondary: var(--button-color-bg-secondary-idle);
  --color-button-secondary-active: var(--button-color-bg-secondary-active);
  --color-button-secondary-active-on-beige: var(--button-color-bg-secondary-active-on-beige);
  --color-button-tertiary: var(--button-color-bg-tertiary-idle);
  --color-button-tertiary-active: var(--button-color-bg-tertiary-active);
  --color-button-tertiary-active-focus: var(--button-color-bg-tertiary-active-focus);
  --color-button-border-primary: var(--button-color-border-primary-idle);
  --color-button-border-primary-active: var(--button-color-border-primary-active);
  --color-button-border-secondary: var(--button-color-border-secondary-idle);
  --color-button-border-secondary-active: var(--button-color-border-secondary-active);
  --color-button-border-tertiary: var(--button-color-border-tertiary-idle);
  --color-button-border-tertiary-active-focus: var(--button-color-border-tertiary-active-focus);
  --color-button-primary-outline: var(--button-outline-primary);
  --color-button-secondary-outline: var(--button-outline-secondary);
  --color-button-tertiary-outline: var(--button-outline-tertiary);

  /* UiB accordion tokens */
  --color-accordion-border: var(--accordion-border-color-idle);
  --color-accordion-border-active: var(--accordion-border-color-active);
  --color-accordion-summary: var(--accordion-summary-color-bg-idle);
  --color-accordion-summary-active: var(--accordion-summary-color-bg-active);
  --color-accordion-summary-foreground-active: var(--accordion-summary-color-fg-active);
  --accordion-border-width-on-desktop: 2px;
  --accordion-border-width-on-mobile: 1.5px;

  /* UiB card tokens */
  --color-card-active: var(--card-color-bg-active);
  --color-card-article: transparent;

  /* UiB link tokens */
  --color-link-list-item-color-fg-idle: var(--link-list-item-color-fg-idle);
  --color-link-list-item-color-fg-active-on-beige: var(--link-list-item-color-fg-active-on-beige);
  --color-link-list-item-color-fg-active-focus-on-beige: var(--link-list-item-color-fg-active-focus-on-beige);
  --color-link-list-item-color-bg-idle: var(--link-list-item-color-bg-idle);
  --color-link-list-item-color-bg-idle-on-beige: var(--link-list-item-color-bg-idle-on-beige);
  --color-link-list-item-color-bg-active: var(--link-list-item-color-bg-active);
  --color-link-list-item-color-bg-active-on-beige: var(--link-list-item-color-bg-active-on-beige);
  --color-link-list-item-color-bg-active-focus-on-beige: var(--link-list-item-color-bg-active-focus-on-beige);
  --color-link-list-item-color-border-active-on-beige: var(--link-list-item-color-border-active-on-beige);
  --color-link-list-item-color-border-idle: transparent;
  --color-link-list-item-color-outline-active: var(--link-list-item-color-outline-active);
  --color-link-list-item-color-outline-active-on-beige: var(--link-list-item-color-outline-active-on-beige);
  --color-link-list-simple-item-color-fg-idle: var(--link-list-simple-item-color-fg-idle);
  --color-link-list-simple-item-color-fg-active: var(--link-list-simple-item-color-fg-active);
  --color-link-list-simple-item-color-fg-active-focus: var(--link-list-simple-item-color-fg-active-focus);
  --color-link-list-simple-item-color-bg-idle: transparent;
  --color-link-list-simple-item-color-bg-active: var(--link-list-simple-item-color-bg-active);
  --color-link-list-simple-item-color-bg-active-focus: var(--link-list-simple-item-color-bg-active-focus);
  --color-link-list-simple-item-color-border-idle: var(--link-list-simple-item-color-border-idle);
  --color-link-list-simple-item-color-border-active: var(--link-list-simple-item-color-border-active);
  --color-link-list-simple-item-color-border-active-focus: transparent;
  --color-link-color-fg-idle: var(--link-color-fg-idle);
  --color-link-color-fg-active: var(--link-color-fg-active);
  --color-link-color-bg-active: var(--link-color-bg-active);
  --color-link-color-border-idle: var(--link-color-border-idle);
  --color-link-color-border-visited: var(--link-color-border-visited);
}

/* ===================================================================
   TW-PROSE - CSS-only Typography for Tailwind CSS v4
   Compatible with @utility directives and Tailwind v4 variables
   =================================================================== */

   @utility ub-prose {
    color: var(--tw-prose-body);
    font-size: var(--text-base);
    line-height: calc(var(--leading-normal) + 0.25);

    & :where(p):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      margin-top: 1.25em;
      margin-bottom: 1.25em;
    }

    & :where([class~='lead']):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      color: var(--tw-prose-lead);
      font-size: 1.25em;
      line-height: 1.6;
      margin-top: 1.2em;
      margin-bottom: 1.2em;
    }

    & :where(a):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      color: var(--tw-prose-links);
      text-decoration: underline;
      font-weight: var(--font-weight-medium);
    }

    & :where(strong):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      color: var(--tw-prose-bold);
      font-weight: var(--font-weight-semibold);
    }

    & :where(a strong):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      color: inherit;
    }

    & :where(blockquote strong):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      color: inherit;
    }

    & :where(thead th strong):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      color: inherit;
    }

    & :where(ol):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      list-style-type: decimal;
      margin-top: 1.25em;
      margin-bottom: 1.25em;
      padding-inline-start: 1.625em;
    }

    & :where(ol[type='A']):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      list-style-type: upper-alpha;
    }

    & :where(ol[type='a']):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      list-style-type: lower-alpha;
    }

    & :where(ol[type='A' s]):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      list-style-type: upper-alpha;
    }

    & :where(ol[type='a' s]):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      list-style-type: lower-alpha;
    }

    & :where(ol[type='I']):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      list-style-type: upper-roman;
    }

    & :where(ol[type='i']):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      list-style-type: lower-roman;
    }

    & :where(ol[type='I' s]):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      list-style-type: upper-roman;
    }

    & :where(ol[type='i' s]):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      list-style-type: lower-roman;
    }

    & :where(ol[type='1']):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      list-style-type: decimal;
    }

    & :where(ul):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      list-style-type: disc;
      margin-top: 1.25em;
      margin-bottom: 1.25em;
      padding-inline-start: 1.625em;
    }

    & :where(ol > li):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *))::marker {
      font-weight: var(--font-weight-normal);
      color: var(--tw-prose-counters);
    }

    & :where(ul > li):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *))::marker {
      color: var(--tw-prose-bullets);
    }

    & :where(dt):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      color: var(--tw-prose-headings);
      font-weight: var(--font-weight-semibold);
      margin-top: 1.25em;
    }

    & :where(hr):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      border-color: var(--tw-prose-hr);
      border-top-width: 1px;
      margin-top: 3em;
      margin-bottom: 3em;
    }

    & :where(blockquote):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      font-weight: var(--font-weight-medium);
      font-style: italic;
      color: var(--tw-prose-quotes);
      border-inline-start-width: 0.25rem;
      border-inline-start-color: var(--tw-prose-quote-borders);
      quotes: '\201C' '\201D' '\2018' '\2019';
      margin-top: 1.6em;
      margin-bottom: 1.6em;
      padding-inline-start: 1em;
    }

    &
      :where(blockquote p:first-of-type):not(
        :where([class~='not-ub-prose'], [class~='not-ub-prose'] *)
      )::before {
      content: open-quote;
    }

    &
      :where(blockquote p:last-of-type):not(
        :where([class~='not-ub-prose'], [class~='not-ub-prose'] *)
      )::after {
      content: close-quote;
    }

    & :where(h1):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      color: var(--tw-prose-headings);
      font-weight: var(--font-weight-extrabold);
      font-size: 2.25em;
      margin-top: 0;
      margin-bottom: 0.8888889em;
      line-height: 1.1111111;
    }

    & :where(h1 strong):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      font-weight: var(--font-weight-black);
      color: inherit;
    }

    & :where(h2):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      color: var(--tw-prose-headings);
      font-weight: var(--font-weight-bold);
      font-size: 1.5em;
      margin-top: 2em;
      margin-bottom: 1em;
      line-height: 1.3333333;
    }

    & :where(h2 strong):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      font-weight: var(--font-weight-extrabold);
      color: inherit;
    }

    & :where(h3):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      color: var(--tw-prose-headings);
      font-weight: var(--font-weight-semibold);
      font-size: 1.25em;
      margin-top: 1.6em;
      margin-bottom: 0.6em;
      line-height: 1.6;
    }

    & :where(h3 strong):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      font-weight: var(--font-weight-bold);
      color: inherit;
    }

    & :where(h4):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      color: var(--tw-prose-headings);
      font-weight: var(--font-weight-semibold);
      margin-top: 1.5em;
      margin-bottom: 0.5em;
      line-height: var(--leading-normal);
    }

    & :where(h4 strong):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      font-weight: var(--font-weight-bold);
      color: inherit;
    }

    & :where(img):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      margin-top: 2em;
      margin-bottom: 2em;
    }

    & :where(picture):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      display: block;
      margin-top: 2em;
      margin-bottom: 2em;
    }

    & :where(video):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      margin-top: 2em;
      margin-bottom: 2em;
    }

    & :where(kbd):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      font-weight: var(--font-weight-medium);
      font-family: inherit;
      color: var(--tw-prose-kbd);
      box-shadow:
        0 0 0 1px oklch(from var(--tw-prose-kbd-shadows) l c h / 10%),
        0 3px 0 oklch(from var(--tw-prose-kbd-shadows) l c h / 10%);
      font-size: 0.875em;
      border-radius: 0.3125rem;
      padding-top: 0.1875em;
      padding-inline-end: 0.375em;
      padding-bottom: 0.1875em;
      padding-inline-start: 0.375em;
    }

    & :where(code):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      color: var(--tw-prose-code);
      font-weight: var(--font-weight-semibold);
      font-size: 0.875em;
    }

    & :where(code):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *))::before {
      content: '`';
    }

    & :where(code):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *))::after {
      content: '`';
