      padding-inline-end: 0.6em;
      padding-bottom: 0.8em;
      padding-inline-start: 0.6em;
    }

    & :where(thead th:first-child):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      padding-inline-start: 0;
    }

    & :where(thead th:last-child):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      padding-inline-end: 0;
    }

    & :where(tbody td, tfoot td):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      padding-top: 0.8em;
      padding-inline-end: 0.6em;
      padding-bottom: 0.8em;
      padding-inline-start: 0.6em;
    }

    &
      :where(tbody td:first-child, tfoot td:first-child):not(
        :where([class~='not-ub-prose'], [class~='not-ub-prose'] *)
      ) {
      padding-inline-start: 0;
    }

    &
      :where(tbody td:last-child, tfoot td:last-child):not(
        :where([class~='not-ub-prose'], [class~='not-ub-prose'] *)
      ) {
      padding-inline-end: 0;
    }

    & :where(figure):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      margin-top: 2em;
      margin-bottom: 2em;
    }

    & :where(figure > *):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      margin-top: 0;
      margin-bottom: 0;
    }

    & :where(figcaption):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      font-size: 0.8333333em;
      line-height: 1.6;
      margin-top: 1em;
    }

    & :where(.prose-2xl > :first-child):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      margin-top: 0;
    }

    & :where(.prose-2xl > :last-child):not(:where([class~='not-ub-prose'], [class~='not-ub-prose'] *)) {
      margin-bottom: 0;
    }
  }

  /* Invert (for dark mode) */
  @utility prose-invert {
    --tw-prose-body: var(--tw-prose-invert-body);
    --tw-prose-headings: var(--tw-prose-invert-headings);
